      SUBROUTINE CAB2 (RC, TC, RA, TA, RB, TB)CC     CALCULATES MATRIX PRODUCE IN SECOND ORDERCC     LIST OF COMMON BLOCKSC      INCLUDE 'TMUL.CIN'CC     LOCAL VARIABLESC      REAL  RA(6,6), RB(6,6), RC(6,6)      REAL  TA(5,21), TB(5,21), TC(5,21)CC-----------------------------------------------------------      CALL CAB(RC,RA,RB)C      TMUL = .FALSE.      TMULT = .FALSE.      DO 5 I1 = 1, 5      DO 5 I23 = 1, 21      IF (TA(I1,I23) .NE. 0.0) THEN        TMUL = .TRUE.        IF (I1 .LE. 4) TMULT = .TRUE.        GO TO 50      ENDIF    5 CONTINUEC   50 DO 90 I1 = 1, 5      DO 90 I23 = 1, 21      S = 0.0      DO 80 I4 = 1, 5      S = S + RA(I1,I4)*TB(I4,I23)   80 CONTINUE      TC(I1,I23) = S   90 CONTINUEC      IF (.NOT. TMUL) GO TO 200      I1MIN = 1      IF (.NOT. TMULT) I1MIN = 5C      DO 150 I1 = I1MIN, 5      DO 150 I2 = 1, 6      INDA = 0      DO 150 I5 = 1, 6      TRR = 0.0      DO 110 I4 = 1, I5      INDA  = INDA + 1      TRR = TRR + TA(I1,INDA)*RB(I4,I2)  110 CONTINUEC      IF (TRR .EQ. 0.0) GO TO 150      DO 120 I3 = 1, 6      I23 = INDEX2(I2,I3)      TC(I1,I23) = TC(I1,I23) + TRR*RB(I5,I3)  120 CONTINUE  150 CONTINUEC  200 RETURN      END